function validate([s]) {
  if (typeof s !== 'string') return 's must be a string.';
  if (s.includes('@')) {
    if (s.length < 8 || s.length > 40) return 'An email has 8 to 40 characters.';
    if (!/^[A-Za-z]{2,}@[A-Za-z]+\.[A-Za-z]+$/.test(s)) return "An email is name@domain: a name of 2+ letters and a domain of letters with one '.' inside.";
    return null;
  }
  if (s.length < 10 || s.length > 20) return 'A phone number has 10 to 20 characters.';
  if (!/^[0-9+\-() ]+$/.test(s)) return 'A phone number has only digits, spaces and ( ) - +.';
  const digitCount = s.replace(/[^0-9]/g, '').length;
  if (digitCount < 10 || digitCount > 13) return 'A phone number has 10 to 13 digits.';
  return null;
}

