function maskPII(s) {
  const at = s.indexOf('@');
  if (at >= 0) {
    const lower = s.toLowerCase();
    return lower[0] + '*****' + lower[at - 1] + lower.slice(at);
  }
  let digits = '';
  for (const ch of s) {
    if (ch >= '0' && ch <= '9') {
      digits += ch;
    }
  }
  const local = '***-***-' + digits.slice(-4);
  const countryLength = digits.length - 10;
  if (countryLength === 0) {
    return local;
  }
  return '+' + '*'.repeat(countryLength) + '-' + local;
}

