function maskPII(s) {
  // Recognise each format with a regular expression and use a lookup table for the prefix.
  const email = /^([A-Za-z]+)@([A-Za-z]+\.[A-Za-z]+)$/.exec(s);
  if (email) {
    const name = email[1].toLowerCase();
    return name.charAt(0) + '*****' + name.charAt(name.length - 1) + '@' + email[2].toLowerCase();
  }
  const digits = s.replace(/[^0-9]/g, '').split('');
  const prefixes = ['', '+*-', '+**-', '+***-'];
  const last = digits.slice(digits.length - 4).join('');
  return prefixes[digits.length - 10] + '***-***-' + last;
}

