function generate(rand, size) {
  const pick = (n) => Math.floor(rand() * n);
  const letters = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ';
  const word = (len) => {
    let w = '';
    for (let i = 0; i < len; i++) w += letters[pick(letters.length)];
    return w;
  };
  if (rand() < 0.5) {
    for (;;) {
      const nameLen = size === 'large' ? 10 + pick(20) : 2 + pick(5);
      const s = word(nameLen) + '@' + word(1 + pick(10)) + '.' + word(1 + pick(6));
      if (s.length >= 8 && s.length <= 40) return [s];
    }
  }
  const separators = '+-() ';
  for (;;) {
    const count = 10 + pick(4);
    const parts = [];
    for (let i = 0; i < count; i++) parts.push(String(pick(10)));
    let s = '';
    const budget = size === 'large' ? 20 - count : pick(21 - count);
    let extras = 0;
    if (count > 10 && rand() < 0.6) {
      s += '+';
      extras++;
    }
    for (let i = 0; i < count; i++) {
      s += parts[i];
      while (i < count - 1 && extras < budget && rand() < 0.35) {
        s += separators[pick(separators.length)];
        extras++;
      }
    }
    if (s.length >= 10 && s.length <= 20) return [s];
  }
}
